        {
            "row": [", ".join(row) for row in duplicate_counts],
            "count": list(duplicate_counts.values()),
        }
    )

    ax = duplicate_df.plot(
        kind="bar",
        x="row",
        y="count",
        legend=False,
        title="Duplicate CSV Rows",
        xlabel="Duplicate row",
        ylabel="Count",
    )
    plt.tight_layout()

    return duplicate_counts, ax

