import pandas as pd
import re
import random


def task_func(s: str, seed: int = 0) -> pd.DataFrame:
    products = ["Apple", "Banana", "Orange", "Pear", "Grape"]
    rng = random.Random(seed)
    code_to_product = {}
    rows = []

    for line in s.splitlines():
        line = line.strip()
        if not line:
            continue

        parts = re.split(r"\s+", line, maxsplit=4)
        if len(parts) < 4:
            continue

        product_id, quantity, code, price = parts[:4]
        description = parts[4].strip() if len(parts) == 5 else ""

        if code not in code_to_product:
            code_to_product[code] = rng.choice(products)

        rows.append(
            {
                "ID": product_id.strip(),
                "Quantity": int(quantity.strip()),
                "Code": code.strip(),
                "Price": int(price.strip()),
                "Product": code_to_product[code],
                "Description": description,
            }
        )

    return pd.DataFrame(
        rows,
        columns=["ID", "Quantity", "Code", "Price", "Product", "Description"],
    )

import itertools
import math
from pandas import Series


def task_func(elements, subset_size, top_n=2):
    if subset_size == 0 or subset_size > len(elements):
        return 1, Series(dtype=int)

    subset_sums = [
        sum(subset)
        for subset in itertools.combinations(elements, subset_size)
    ]

    product_of_sums = math.prod(subset_sums)
    top_sums = Series(sorted(subset_sums, reverse=True)[:top_n])

    return product_of_sums, top_sums

import subprocess
import os
import signal
import time


def task_func(process_name: str) -> int:
    if not process_name:
        return 0

    try:
        if os.name == "nt":
            result = subprocess.run(
                ["tasklist", "/FI", f"IMAGENAME eq {process_name}", "/FO", "CSV", "/NH"],
                capture_output=True,
                text=True,
                check=False,
            )
            pids = []
            for line in result.stdout.splitlines():
                parts = line.strip().strip('"').split('","')
                if len(parts) >= 2 and parts[1].isdigit():
                    pids.append(int(parts[1]))
        else:
            result = subprocess.run(
                ["pgrep", "-x", process_name],
                capture_output=True,
                text=True,
                check=False,
            )
            pids = [
                int(line)
                for line in result.stdout.splitlines()
                if line.strip().isdigit()
            ]

        pids = [pid for pid in pids if pid != os.getpid()]

        for pid in pids:
            try:
                os.kill(pid, signal.SIGTERM)
            except (ProcessLookupError, PermissionError, OSError):
                pass

        time.sleep(1)
        return len(pids)
    except (FileNotFoundError, subprocess.SubprocessError, ValueError):
        return 0

