import os
import shutil

# Constants
BACKUP_DIR = '/tmp/backup'


def get_unique_backup_dir():
    return "/fake/backup/path"


def task_func(directory):
    backup_directory = get_unique_backup_dir()
    errors = []

    try:
        if not os.path.isdir(directory):
            return backup_directory, [f"Directory does not exist: {directory}"]

        os.makedirs(backup_directory, exist_ok=True)

        for entry in os.scandir(directory):
            source = entry.path
            destination = os.path.join(backup_directory, entry.name)

            try:
                if entry.is_dir(follow_symlinks=False):
                    shutil.copytree(source, destination, dirs_exist_ok=True)
                else:
                    shutil.copy2(source, destination)
            except OSError as error:
                errors.append(str(error))
                continue

            try:
                if entry.is_dir(follow_symlinks=False):
                    shutil.rmtree(source)
                else:
                    os.remove(source)
            except OSError as error:
                errors.append(str(error))

    except OSError as error:
        errors.append(str(error))

    return backup_directory, errors

import subprocess
import os
import shutil
from glob import glob


def task_func(src_folder, dst_folder):
    failed_files = []

    if not os.path.isdir(src_folder):
        return {
            "success": False,
            "message": f"Source folder does not exist: {src_folder}",
            "failed_files": [],
        }

    try:
        os.makedirs(dst_folder, exist_ok=True)
    except OSError as exc:
        return {
            "success": False,
            "message": f"Could not create destination folder: {exc}",
            "failed_files": [],
        }

    files = [path for path in glob(os.path.join(src_folder, "*")) if os.path.isfile(path)]
    processes = []

    for file_path in files:
        processes.append(
            (file_path, subprocess.Popen(["gzip", "-f", file_path]))
        )

    compressed_files = []

    for file_path, process in processes:
        return_code = process.wait()
        compressed_path = file_path + ".gz"

        if return_code != 0 or not os.path.isfile(compressed_path):
            failed_files.append(os.path.basename(file_path))
        else:
            compressed_files.append((file_path, compressed_path))

    for original_path, compressed_path in compressed_files:
        try:
            shutil.move(compressed_path, os.path.join(dst_folder, os.path.basename(compressed_path)))
        except (OSError, shutil.Error):
            failed_files.append(os.path.basename(original_path))

    success = not failed_files
    message = (
        "All files were compressed and moved successfully."
        if success
        else f"Some files could not be compressed or moved: {len(failed_files)} failed."
    )

    return {
        "success": success,
        "message": message,
        "failed_files": failed_files,
    }

