import matplotlib.pyplot as plt


def task_func(data_file_path: str):
    data = pd.read_csv(data_file_path)

    def convert_value(value):
        if isinstance(value, str):
            value = value.strip().replace(",", ".")
        return float(value)

    data = data.apply(lambda column: column.map(convert_value))

    means = data.mean()
    std_devs = data.std()

    axes = []
    for column in data.columns:
        _, ax = plt.subplots()
        ax.hist(data[column].dropna())
        ax.set_title(f"Histogram of {column}")
        ax.set_xlabel(column)
        ax.set_ylabel("Frequency")
        axes.append(ax)

    anova_results = pd.DataFrame(columns=["F-value", "P-value"])

    if len(data.columns) >= 2:
        results = {}
        for i, first_column in enumerate(data.columns[:-1]):
            for second_column in data.columns[i + 1:]:
                first_values = data[first_column].dropna()
                second_values = data[second_column].dropna()
                f_value, p_value = f_oneway(first_values, second_values)
                results[f"{first_column} vs {second_column}"] = {
                    "F-value": f_value,
                    "P-value": p_value,
                }

        anova_results = pd.DataFrame.from_dict(results, orient="index")
        anova_results.index.name = "Comparison"

    return means, std_devs, axes, anova_results

