    rng = random.Random(seed)
    result = []

    for char in text:
        if char in string.ascii_letters:
            result.append(rng.choice(string.ascii_lowercase))
        elif char in string.digits:
            result.append(rng.choice(string.digits))
        elif char == " ":
            if rng.random() < 0.5:
                result.append(rng.choice(string.digits))
            else:
                result.append(rng.choice(string.ascii_lowercase))
        else:
            result.append(char)

    return "".join(result)

import re
import json
from collections import Counter


def task_func(json_str, top_n=10):
    data = json.loads(json_str)
    url_pattern = re.compile(r"https?://[A-Za-z0-9.-]+(?::\d+)?(?:/[^\s\"'<>]*)?")

    def strings(value):
        if isinstance(value, dict):
            for key, item in value.items():
                yield from strings(key)
                yield from strings(item)
        elif isinstance(value, (list, tuple)):
            for item in value:
                yield from strings(item)
        elif isinstance(value, str):
            yield value

    urls = []
    for value in strings(data):
        urls.extend(url_pattern.findall(value))

    return dict(Counter(urls).most_common(top_n))

