import pandas as pd
import csv
from difflib import ndiff


def task_func(file_path1, file_path2, delimiter=',', quotechar='"'):
    def read_csv_lines(file_path):
        try:
            with open(file_path, 'r', newline='', encoding='utf-8') as file:
                raw_lines = file.read().splitlines()

            if not raw_lines:
                raise ValueError(f"CSV file is empty: {file_path}")

            with open(file_path, 'r', newline='', encoding='utf-8') as file:
                list(csv.reader(file, delimiter=delimiter, quotechar=quotechar))

            return raw_lines
        except FileNotFoundError:
            raise
        except ValueError:
            raise
        except OSError as error:
            raise Exception(f"Unable to read CSV file: {file_path}") from error

    lines1 = read_csv_lines(file_path1)
    lines2 = read_csv_lines(file_path2)

    differences = []
    line_number1 = 0
    line_number2 = 0

    for difference in ndiff(lines1, lines2):
        status = difference[:2]
        content = difference[2:]

        if status == '? ':
            continue

        if status == '  ':
            line_number1 += 1
            line_number2 += 1
            differences.append((line_number1, ' ', content))
        elif status == '- ':
            line_number1 += 1
            differences.append((line_number1, '-', content))
        elif status == '+ ':
            line_number2 += 1
            differences.append((line_number2, '+', content))

    return pd.DataFrame(
        differences,
        columns=['Line Number', 'Status', 'Content']
    )

