import re

def task_func(data_list, seed=None):
    rng = random.Random(seed)
    modified_strings = []

    for original in data_list:
        substrings = re.split(r",", original)

        operations = ["replace", "shuffle", "randomize"]
        if len(substrings) > 1:
            operations.insert(0, "remove")

        operation = rng.choice(operations)

        if operation == "remove":
            substrings.pop(rng.randrange(len(substrings)))
        elif operation == "replace":
            substrings[rng.randrange(len(substrings))] = "random_string"
        elif operation == "shuffle":
            rng.shuffle(substrings)
        elif operation == "randomize":
            substrings = rng.sample(substrings, len(substrings))

        modified_strings.append(",".join(substrings))

    return pd.DataFrame({
        "Original String": data_list,
        "Modified String": modified_strings
    })

import os
