from threading import Thread


def task_func(ip_range, port):
    results = {}

    def check_ip(ip):
        ip_address = str(ip)
        try:
            with socket.create_connection((ip_address, port), timeout=1):
                results[ip_address] = True
        except (OSError, ValueError):
            results[ip_address] = False

    threads = []
    for ip in IPv4Network(ip_range, strict=False):
