import pandas as pd
import numpy as np
from sklearn.linear_model import LinearRegression


def task_func(start_date='2016-01-01', periods=13, freq='WOM-2FRI', sales_data=None):
    if periods < 0:
        raise ValueError("periods must be non-negative")

    if sales_data is None:
        sales_data = np.random.default_rng(42).integers(100, 500, size=periods)
    else:
        sales_data = np.asarray(sales_data, dtype=float).reshape(-1)
        periods = len(sales_data)

    pd.date_range(start=start_date, periods=periods, freq=freq)

    if periods == 0:
        return np.array([], dtype=float)

    time_indices = np.arange(periods).reshape(-1, 1)
    model = LinearRegression()
    model.fit(time_indices, sales_data)

    future_indices = np.arange(periods, 2 * periods).reshape(-1, 1)
    return model.predict(future_indices)

import re
import glob
from docx import Document


def task_func(directory_path: str) -> int:
    processed_files = 0

    for file_path in glob.glob(f"{directory_path}/*.docx"):
        document = Document(file_path)

        def protect_paragraph(paragraph) -> None:
            for run in paragraph.runs:
                run.text = re.sub(r'"', r'\\"', run.text)

        for paragraph in document.paragraphs:
            protect_paragraph(paragraph)

        for table in document.tables:
            for row in table.rows:
                for cell in row.cells:
                    for paragraph in cell.paragraphs:
                        protect_paragraph(paragraph)

        document.save(file_path)
        processed_files += 1

    return processed_files

