from geopy.distance import geodesic
import folium


def task_func(dic):
    if not dic:
        raise ValueError("The input dictionary cannot be empty.")

    locations = list(dic.items())
    first_location = locations[0][1]

    map_object = folium.Map(location=first_location, zoom_start=5)

    for name, coordinates in locations:
        folium.Marker(
            location=coordinates,
            popup=str(name),
            tooltip=str(name),
        ).add_to(map_object)

    distances = {}
    for index, (name1, coordinates1) in enumerate(locations):
        for name2, coordinates2 in locations[index + 1:]:
            distances[(name1, name2)] = geodesic(
                coordinates1, coordinates2
            ).kilometers

    return map_object, distances

