import unicodedata

def task_func(directory):
    result = {}

    for path in pathlib.Path(directory).iterdir():
        if path.is_file():
            normalized_name = unicodedata.normalize(
                "NFKD", path.name
            ).encode("ascii", "ignore").decode("ascii")

            file_hash = md5()
            with path.open("rb") as file:
                for chunk in iter(lambda: file.read(8192), b""):
                    file_hash.update(chunk)

            result[normalized_name] = {
                "Size": path.stat().st_size,
                "MD5 Hash": file_hash.hexdigest(),
            }

    return result

import pandas as pd
import itertools
import random


def task_func(colors, states):
    combinations = [
        f"{color}:{state}"
        for color, state in itertools.product(colors, states)
    ]
    random.shuffle(combinations)

    num_columns = min(len(colors), len(states))

    if num_columns == 0:
        return pd.DataFrame()

    base_size, remainder = divmod(len(combinations), num_columns)
    columns = {}
    start = 0

    for column_index in range(num_columns):
        size = base_size + (1 if column_index < remainder else 0)
        columns[column_index] = combinations[start:start + size]
        start += size

    return pd.DataFrame(columns)

