OUTPUT_DIR = './output'
import os


def task_func(directory: str, pattern: str = r"(?<!Distillr)\\AcroTray\.exe") -> dict:
    compiled_pattern = re.compile(pattern)
    result = {}

    for root, _, files in os.walk(directory):
        for filename in files:
            file_path = os.path.join(root, filename)

            if compiled_pattern.search(file_path):
                digest = hashlib.sha256()
                with open(file_path, "rb") as file:
                    for chunk in iter(lambda: file.read(8192), b""):
                        digest.update(chunk)
                result[file_path] = digest.hexdigest()

    return result

import re
import json
import requests


def task_func(data_url: str) -> list:
    try:
        response = requests.get(data_url)
        data = json.loads(response.text)
        text = json.dumps(data, ensure_ascii=False)

        bracket_depth = [0] * (len(text) + 1)
        depth = 0
        in_string = False
        escaped = False

        for index, char in enumerate(text):
            bracket_depth[index] = depth

            if in_string:
                if escaped:
                    escaped = False
                elif char == "\\":
                    escaped = True
                elif char == '"':
                    in_string = False
            elif char == '"':
                in_string = True
            elif char == "[":
                depth += 1
            elif char == "]":
                depth = max(0, depth - 1)

        pattern = re.compile(r'"name"\s*:\s*("(?:\\.|[^"\\])*")')
        names = []

        for match in pattern.finditer(text):
            if bracket_depth[match.start(1)] > 0:
                continue

            name = json.loads(match.group(1))
            if isinstance(name, str) and not (
                name.startswith("[") and name.endswith("]")
            ):
                names.append(name)

        return names
    except Exception:
        return "Invalid url input"

