from collections import Counter
import os
import csv

# Constants
FILE_DIR = './yourdictfiles/'


def task_func(output_file, test_directory):
    try:
        if not isinstance(output_file, (str, os.PathLike)):
            return 0
        if not isinstance(test_directory, (str, os.PathLike)):
            return 0
        if not os.path.isdir(test_directory):
            return 0

        word_counts = Counter()

        for filename in os.listdir(test_directory):
            file_path = os.path.join(test_directory, filename)
            if filename.lower().endswith('.txt') and os.path.isfile(file_path):
                with open(file_path, 'r', encoding='utf-8') as file:
                    word_counts.update(file.read().split())

        total_words = sum(word_counts.values())

        with open(output_file, 'w', newline='', encoding='utf-8') as csv_file:
            writer = csv.writer(csv_file)
            writer.writerow(['Word', 'Count'])
            for word, count in word_counts.items():
                writer.writerow([word, count])

        return total_words
    except Exception:
        return 0

import numpy as np
import cv2
import os

def task_func(image_path='image.jpg', threshold=128):
    if not os.path.exists(image_path):
        raise FileNotFoundError(f"Image file not found: {image_path}")

    if isinstance(threshold, bool) or not isinstance(threshold, (int, np.integer)):
        raise ValueError("Threshold must be an integer between 0 and 255.")

    if not 0 <= threshold <= 255:
        raise ValueError("Threshold must be an integer between 0 and 255.")

    image = cv2.imread(image_path, cv2.IMREAD_COLOR)
    if image is None:
        raise FileNotFoundError(f"Unable to read image file: {image_path}")

    grayscale = cv2.cvtColor(image, cv2.COLOR_BGR2GRAY)
    _, binarized = cv2.threshold(grayscale, int(threshold), 255, cv2.THRESH_BINARY)

    return grayscale, binarized

