    X = sm.add_constant(filtered_df[columns[1:]])

    return sm.OLS(y, X).fit()

import sqlite3
import numpy as np
from random import choice, seed


def task_func(db_path, table_name, num_entries, random_seed=None):
    if num_entries < 0:
        raise ValueError("num_entries cannot be negative")

    names = ["John", "Jane", "Steve", "Emma", "Liam", "Olivia"]

    if random_seed is not None:
        seed(random_seed)
        np.random.seed(random_seed)

    def quote_identifier(identifier):
        return '"' + str(identifier).replace('"', '""') + '"'

    connection = sqlite3.connect(db_path)
    try:
        table = quote_identifier(table_name)
        connection.execute(
            f"""
            CREATE TABLE IF NOT EXISTS {table} (
                name TEXT,
                age INTEGER,
                height INTEGER
            )
            """
        )

        rows = [
            (
                choice(names),
                int(np.random.randint(18, 65)),
                int(np.random.randint(150, 200)),
            )
            for _ in range(num_entries)
        ]

        connection.executemany(
            f"INSERT INTO {table} (name, age, height) VALUES (?, ?, ?)",
            rows,
        )
        connection.commit()
        return len(rows)
    finally:
        connection.close()

