from typing import List, Union
import numpy as np
import scipy.fft


def task_func(data: List[Union[int, str]], repetitions: int = 1):
    if not data or repetitions <= 0:
        return {
            "mode": np.array([]),
            "count": np.array([], dtype=int),
        }

    repeated_data = data * repetitions
    values, counts = np.unique(np.array(repeated_data), return_counts=True)
    max_count = counts.max()
    modes = values[counts == max_count]
    mode_counts = counts[counts == max_count]

    order = np.argsort(modes)
    return {
        "mode": modes[order],
        "count": mode_counts[order],
    }

import numpy as np
import pandas as pd


def task_func(products, n_samples=100, sales_lower=50, sales_upper=200,
              profit_margin_min=0.1, profit_margin_max=0.5, random_seed=42):
    if not isinstance(products, list) or not all(isinstance(product, str) for product in products):
        raise TypeError("products must be a list of strings")

    if isinstance(n_samples, bool) or not isinstance(n_samples, (int, np.integer)) or n_samples <= 0:
        raise ValueError("n_samples must be a positive integer")

    numeric_values = (
        sales_lower,
        sales_upper,
        profit_margin_min,
        profit_margin_max,
    )
    if any(isinstance(value, bool) or not isinstance(value, (int, float, np.number))
           for value in numeric_values):
        raise TypeError("sales and profit margin parameters must be numeric")

    if sales_lower > sales_upper:
        raise ValueError("sales_lower must not be greater than sales_upper")

    columns = ["Product", "Total Sales", "Total Profit"]
    if not products:
        return pd.DataFrame(columns=columns)

    rng = np.random.default_rng(random_seed)

    product_data = rng.choice(products, size=n_samples)
    sales = rng.uniform(sales_lower, sales_upper, size=n_samples)
    profit_margins = rng.uniform(
        profit_margin_min,
        profit_margin_max,
        size=n_samples,
    )
    profit = sales * profit_margins

    data = pd.DataFrame({
        "Product": product_data,
        "Sales": sales,
        "Profit": profit,
    })

    report = (
        data.groupby("Product", as_index=False)
        .agg(
            **{
                "Total Sales": ("Sales", "sum"),
                "Total Profit": ("Profit", "sum"),
            }
        )
        .sort_values("Total Profit", ascending=False, kind="mergesort")
        .reset_index(drop=True)
