def task_func(L):
    if not isinstance(L, list):
        raise TypeError("L must be a list of lists of integers")

    for sublist in L:
        if not isinstance(sublist, list):
            raise TypeError("L must be a list of lists of integers")
        if any(not isinstance(value, (int, np.integer)) or isinstance(value, bool)
               for value in sublist):
