import importlib
from pkgutil import iter_modules

def task_func(package_name):
    try:
        package = importlib.import_module(package_name)
    except ImportError as exc:
        raise ImportError(
            f"Package '{package_name}' was not found. "
            f"Please install it with: pip install {package_name}"
        ) from exc

    package_paths = list(getattr(package, "__path__", []))

    if not package_paths and getattr(package, "__file__", None):
        package_paths = [os.path.dirname(package.__file__)]

    for path in package_paths:
        if path not in sys.path:
            sys.path.append(path)

    module_names = []
    for _, module_name, _ in iter_modules(package_paths):
        if module_name not in module_names:
            module_names.append(module_name)

    return module_names

