import re
import pandas as pd
from datetime import datetime


def task_func(log_file):
    pattern = re.compile(
        r"^\s*([^:\s]+):\s*\[([^\]]+)\]\s*-\s*(.*)\s*$"
    )
    entries = []

    with open(log_file, "r", encoding="utf-8") as file:
        for line in file:
            match = pattern.match(line)
            if not match:
                continue

            message_type, timestamp, message = match.groups()

            try:
                datetime.strptime(timestamp, "%Y-%m-%d %H:%M:%S")
            except ValueError as exc:
                raise ValueError(
                    f"Invalid timestamp: {timestamp}"
                ) from exc

            entries.append(
                {
                    "Type": message_type,
                    "Timestamp": timestamp,
                    "Message": message,
                }
            )

    if not entries:
        raise ValueError("No valid log entries found")

    output_file = re.sub(r"\.[^.\\/]+$", ".csv", log_file)
    if output_file == log_file:
        output_file = f"{log_file}.csv"

    pd.DataFrame(entries).to_csv(output_file, index=False)
    return output_file

