from collections import Counter


def task_func(directory, extensions=[".txt", ".docx", ".xlsx", ".csv"], keep_zero=True):
    if not os.path.isdir(directory):
        raise OSError(f"Directory does not exist: {directory}")

    counts = Counter({extension: 0 for extension in extensions})

    for root, _, files in os.walk(directory):
        for filename in files:
            extension = os.path.splitext(filename)[1]
            if extension in counts:
                counts[extension] += 1

    if not keep_zero:
        counts = Counter(
            extension for extension, count in counts.items() if count > 0
        )

    return counts

