import struct
import io
import gzip


def task_func(newArray):
    buffer = io.BytesIO()

    dtype = newArray.dtype
    kind = dtype.kind
    size = dtype.itemsize
    byte_order = dtype.byteorder

    if byte_order == ">":
        prefix = ">"
    elif byte_order == "<":
        prefix = "<"
    else:
        prefix = "="

    format_map = {
        "b": "b",
        "i": {1: "b", 2: "h", 4: "i", 8: "q"},
        "u": {1: "B", 2: "H", 4: "I", 8: "Q"},
        "f": {2: "e", 4: "f", 8: "d"},
    }

    values = newArray.ravel()

    if kind == "c":
        component_format = {8: "f", 16: "d"}.get(size)
        if component_format is None:
            raise TypeError("Unsupported complex dtype")
        fmt = prefix + component_format * 2
        raw_data = b"".join(
            struct.pack(fmt, value.real, value.imag) for value in values
        )
    elif kind in format_map:
        type_format = format_map[kind]
        if isinstance(type_format, dict):
            type_format = type_format.get(size)
        if type_format is None:
            raise TypeError("Unsupported dtype")
        fmt = prefix + type_format
        raw_data = b"".join(struct.pack(fmt, value.item()) for value in values)
    else:
        raw_data = bytes(newArray.tobytes())

    with gzip.GzipFile(fileobj=buffer, mode="wb") as compressed:
        compressed.write(raw_data)

    return buffer.getvalue()

