import subprocess
import psutil
import time
import os


def task_func(script_path: str, timeout=10) -> dict:
    if not os.path.exists(script_path):
        raise FileNotFoundError(f"Script not found: {script_path}")

    process = subprocess.Popen(["bash", script_path])
    monitored_process = psutil.Process(process.pid)

    cpu_usage = 0.0
    memory_usage = 0
    start_time = time.monotonic()

    try:
        monitored_process.cpu_percent(None)

        while process.poll() is None:
            if time.monotonic() - start_time >= timeout:
                process.terminate()
                try:
                    process.wait(timeout=1)
                except subprocess.TimeoutExpired:
                    process.kill()
                    process.wait()
                break

            try:
                if (
                    not monitored_process.is_running()
                    or monitored_process.status() == psutil.STATUS_ZOMBIE
                ):
                    break

                cpu_usage += monitored_process.cpu_percent(None)
                memory_usage += monitored_process.memory_info().rss
            except (psutil.NoSuchProcess, psutil.ZombieProcess):
                break

            time.sleep(0.1)

        try:
            cpu_usage += monitored_process.cpu_percent(None)
        except (psutil.NoSuchProcess, psutil.ZombieProcess):
            pass

    finally:
        if process.poll() is None:
            process.terminate()
            try:
                process.wait(timeout=1)
            except subprocess.TimeoutExpired:
                process.kill()
                process.wait()

    return {
        "CPU Usage": cpu_usage,
        "Memory Usage": memory_usage,
    }

