# Function to replace acronyms in DataFrame
def task_func(data, mapping):
    result = data.copy()

    if not mapping:
        return result

    keys = [key for key in mapping if isinstance(key, str) and key]
    if not keys:
        return result

    keys.sort(key=len, reverse=True)
    pattern = re.compile(
        r"(?<!\w)(?:" + "|".join(re.escape(key) for key in keys) + r")(?!\w)"
    )

    def replace_acronyms(value):
        if isinstance(value, str):
            return pattern.sub(
                lambda match: str(mapping[match.group(0)]),
                value
            )
        return value

    return result.apply(lambda column: column.map(replace_acronyms))

