import os
import re
from pathlib import Path


def task_func(dir_path: str, predicates: list) -> dict:
    directory = Path(dir_path)

    if not directory.is_dir():
        raise FileNotFoundError(f"Directory does not exist: {dir_path}")

    valid_predicates = []
    seen = set()

    for predicate in predicates:
        try:
            if isinstance(predicate, re.Pattern):
                compiled = predicate
                key = ("regex", compiled.pattern, compiled.flags)
            elif isinstance(predicate, str) and predicate:
                compiled = re.compile(predicate)
                key = ("regex", compiled.pattern, compiled.flags)
            elif callable(predicate):
                compiled = predicate
                key = ("callable", id(predicate))
            else:
                continue
        except re.error:
            continue

        if key not in seen:
            seen.add(key)
            valid_predicates.append(compiled)

    if not valid_predicates:
        raise ValueError("No valid predicates were provided")

    result = {}

    for item in os.listdir(directory):
        checks = []
        for predicate in valid_predicates:
            if callable(predicate) and not isinstance(predicate, re.Pattern):
                checks.append(bool(predicate(item)))
            else:
                checks.append(bool(predicate.search(item)))
        result[item] = checks

    return result

import os
import shutil

def task_func(src_dir, dest_dir, extension):
    os.makedirs(dest_dir, exist_ok=True)
    files_moved = 0

    for entry in os.scandir(src_dir):
        if entry.is_file() and entry.name.endswith(extension):
            shutil.move(entry.path, os.path.join(dest_dir, entry.name))
            files_moved += 1

    return {"files_moved": files_moved}

import random
import re


def task_func(target_words, n_sentences, vocabulary):
    if n_sentences < 0:
        raise ValueError("n_sentences must be non-negative")
    if not vocabulary:
        raise ValueError("vocabulary must not be empty")

    patterns = []
    for target in target_words:
        target = str(target)
        pattern = re.compile(
            r"(?<!\w)" + re.escape(target) + r"(?!\w)",
            re.IGNORECASE,
        )
        replacement = target.replace(" ", "_").lower()
        patterns.append((pattern, replacement))

    sentences = []
    for _ in range(n_sentences):
        sentence = " ".join(random.choices(vocabulary, k=10))
        for pattern, replacement in patterns:
            sentence = pattern.sub(replacement, sentence)
        sentences.append(sentence.lower())

    return sentences

