def task_func(data, columns=['Name', 'Age', 'Occupation'], fill_missing=False, num_range=(0, 100), seed=None):
    column_count = len(columns)
    rows = [
        list(row[:column_count]) + [None] * max(0, column_count - len(row))
        for row in data
    ]

    if fill_missing:
        rng = random.Random(seed)

        numeric_columns = set()
        for index in range(column_count):
            values = [row[index] for row in rows if row[index] is not None]
            if values and all(
                isinstance(value, (int, float)) and not isinstance(value, bool)
                for value in values
            ):
                numeric_columns.add(index)

        for row in rows:
            for index in numeric_columns:
                if row[index] is None:
                    row[index] = rng.randint(num_range[0], num_range[1])

    return pd.DataFrame(rows, columns=columns)

