import ast
import re


def task_func(text_file: str) -> list:
    with open(text_file, "r", encoding="utf-8") as file:
        text = file.read()

    dictionary_strings = re.findall(r"\{[^{}]*\}", text)
    dictionaries = []

    for dictionary_string in dictionary_strings:
        try:
            value = ast.literal_eval(dictionary_string)
            if isinstance(value, dict):
                dictionaries.append(value)
        except (SyntaxError, ValueError):
            continue

    return dictionaries

