import pandas as pd
from datetime import datetime
import random


def task_func(
    epoch_milliseconds,
    random_seed=0,
    products=["Product1", "Product2", "Product3", "Product4", "Product5"],
):
    if isinstance(epoch_milliseconds, bool) or not isinstance(
        epoch_milliseconds, (int, float)
    ):
        raise ValueError("epoch_milliseconds must be a numeric value.")

    if epoch_milliseconds < 0:
        raise ValueError("epoch_milliseconds must be non-negative.")

    if not isinstance(products, (list, tuple)) or len(products) != 5:
        raise ValueError("products must contain exactly five products.")

    if not all(isinstance(product, str) for product in products):
        raise ValueError("All products must be strings.")

    try:
        start_date = datetime.fromtimestamp(epoch_milliseconds / 1000).date()
    except (OverflowError, OSError, ValueError) as exc:
        raise ValueError("Invalid epoch_milliseconds.") from exc

    end_date = datetime.now().date()

    if start_date > end_date:
        raise ValueError("epoch_milliseconds cannot represent a future date.")

    rng = random.Random(random_seed)
    records = []

    for date in pd.date_range(start=start_date, end=end_date, freq="D"):
        for product in products:
            records.append(
                {
                    "Product": product,
                    "Date": date.to_pydatetime(),
                    "Sales": rng.randint(10, 50),
                }
            )

    return pd.DataFrame(records, columns=["Product", "Date", "Sales"])

