import matplotlib.pyplot as plt


def task_func(data, date_format, country, country_codes=None):
    if not isinstance(data, pd.DataFrame):
        raise ValueError("'data' must be a DataFrame")
    if not isinstance(date_format, str):
        raise ValueError("'date_format' must be a string")
    if not isinstance(country_codes, dict):
        raise ValueError("'country_codes' must be a dictionary")
    if country not in country_codes:
        raise ValueError("'country' must be present in 'country_codes'")

    country_code = country_codes[country]
    date_column = next(
        (column for column in data.columns if str(column).lower() in {"date", "dates"}),
        None,
    )

    if country_code in data.columns:
        values = data[country_code]
    elif country in data.columns:
        values = data[country]
    elif date_column is not None:
        country_column = next(
            (
                column
                for column in data.columns
                if str(column).lower() in {"country", "country/region", "country_code"}
            ),
            None,
        )
        if country_column is not None:
            values = data.loc[
                data[country_column].isin({country, country_code}), date_column
            ]
        else:
            values = data[date_column]
    else:
        raise ValueError("No suitable data column was found")

    converted_values = [
        value
        if isinstance(value, datetime)
        else datetime.strptime(str(value), date_format)
        for value in values.dropna()
    ]

    _, ax = plt.subplots()
    ax.hist(converted_values)
    ax.set_title("Date Distribution")
    ax.set_ylabel("Frequency")

    return ax

