import os
import pandas as pd
from datetime import datetime


def task_func(
    excel_directory: str,
    file_name: str,
    column_name: str,
    start_date: str,
    end_date: str,
) -> pd.DataFrame:
    file_path = os.path.join(excel_directory, file_name)

    if not os.path.isfile(file_path):
        raise FileNotFoundError(f"Excel file not found: {file_path}")

    try:
        start = datetime.strptime(start_date, "%Y-%m-%d")
        end = datetime.strptime(end_date, "%Y-%m-%d")
    except (TypeError, ValueError) as exc:
        raise ValueError(
            "start_date and end_date must be in YYYY-MM-DD format"
        ) from exc

    data = pd.read_excel(file_path)

    if column_name not in data.columns:
        raise ValueError(f"Column does not exist: {column_name}")

    date_values = pd.to_datetime(data[column_name], errors="coerce")
    mask = date_values.between(start, end, inclusive="both")

    return data.loc[mask].copy()

