import hashlib
import random
import struct

KEYS = ['470FC614', '4A0FC614', '4B9FC614', '4C8FC614', '4D7FC614']


def task_func(hex_keys=KEYS, seed=42):
    for key in hex_keys:
        try:
            raw_key = bytes.fromhex(key)
        except (TypeError, ValueError) as exc:
            raise ValueError("hex_keys contains invalid hexadecimal strings") from exc

        if len(raw_key) != 4:
            raise ValueError("hex_keys contains invalid hexadecimal strings")

    rng = random.Random(seed)
    selected_key = rng.choice(hex_keys)
    float_value = struct.unpack("!f", bytes.fromhex(selected_key))[0]

    return hashlib.md5(str(float_value).encode()).hexdigest()

