import socket
import select
import queue
from datetime import datetime, timedelta


def task_func(
    server_address="localhost", server_port=12345, buffer_size=1024, run_duration=5
):
    server_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    server_socket.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
    server_socket.setblocking(False)

    clients = {}
    start_time = datetime.now()
    deadline = start_time + timedelta(seconds=run_duration)

    try:
        server_socket.bind((server_address, server_port))
        server_socket.listen()

        while datetime.now() < deadline:
            readable = [server_socket] + list(clients)
            writable = [client for client, pending in clients.items() if not pending]
            exceptional = [server_socket] + list(clients)

            remaining = max(0.0, (deadline - datetime.now()).total_seconds())

            try:
                ready_read, ready_write, ready_exception = select.select(
                    readable, writable, exceptional, remaining
                )
            except (OSError, ValueError):
                break

            if server_socket in ready_exception:
                break

            if server_socket in ready_read:
                try:
                    client_socket, _ = server_socket.accept()
                    client_socket.setblocking(False)
                    clients[client_socket] = queue.Queue()
                except BlockingIOError:
                    pass
                except OSError:
                    pass

            for client_socket in list(clients):
                if client_socket in ready_exception:
                    clients.pop(client_socket, None)
                    try:
                        client_socket.close()
                    except OSError:
                        pass
                    continue

                if client_socket in ready_read:
                    try:
                        data = client_socket.recv(buffer_size)
                        if not data:
                            raise ConnectionError
                        clients[client_socket].put(
                            data + str(datetime.now()).encode()
                        )
                    except (BlockingIOError, ConnectionError, OSError):
                        clients.pop(client_socket, None)
                        try:
                            client_socket.close()
                        except OSError:
                            pass
                        continue

                if client_socket in ready_write and client_socket in clients:
                    pending = clients[client_socket]
                    if not pending.empty():
                        data = pending.queue[0]
                        try:
                            sent = client_socket.send(data)
                            if sent == len(data):
                                pending.get_nowait()
                            else:
                                pending.queue[0] = data[sent:]
                        except (BlockingIOError, OSError):
                            clients.pop(client_socket, None)
                            try:
                                client_socket.close()
                            except OSError:
                                pass
    finally:
        for client_socket in clients:
            try:
                client_socket.close()
            except OSError:
                pass
        server_socket.close()

    return f"Echo server operated for {run_duration} seconds."

import pandas as pd
