import datetime


def task_func(start_year=1980, end_year=2000, email_domain='example.com',
              latin_names=['Sopetón', 'Méndez', 'Gómez', 'Pérez', 'Muñoz'],
              other_names=['Smith', 'Johnson', 'Williams', 'Brown', 'Jones'],
              rng_seed=None):
    rng = np.random.default_rng(rng_seed)

    def correct_encoding(name):
        try:
            return name.encode("latin1").decode("utf-8")
        except (UnicodeEncodeError, UnicodeDecodeError):
            return name

    names = [
        correct_encoding(str(name))
        for name in list(latin_names) + list(other_names)
    ]

    records = []
    for record_id in range(1, 101):
        name = str(rng.choice(names))
        year = int(rng.integers(start_year, end_year + 1))
        month = int(rng.integers(1, 13))

        if year == 0:
            max_day = 28
        else:
            if month == 12:
                next_month = datetime.datetime(year + 1, 1, 1)
            else:
                next_month = datetime.datetime(year, month + 1, 1)
            max_day = (next_month - datetime.timedelta(days=1)).day

        day = int(rng.integers(1, max_day + 1))

        if year == 0:
            date_of_birth = f"{year:04d}-{month:02d}-{day:02d} 00:00:00"
        else:
            date_of_birth = datetime.datetime(year, month, day)

        records.append({
            "ID": record_id,
            "Name": name,
            "Date of Birth": date_of_birth,
            "Email": f"{name.lower()}{year}@{email_domain}",
        })

    return pd.DataFrame(
        records,
        columns=["ID", "Name", "Date of Birth", "Email"]
    )

