import pandas as pd
import numpy as np
from statsmodels.tsa.seasonal import seasonal_decompose


def task_func(start_date='2016-01-01', periods=24, freq='M', model='additive'):
    if periods < 2:
        raise ValueError("periods must be at least 2")
    if model not in {'additive', 'multiplicative'}:
        raise ValueError("model must be 'additive' or 'multiplicative'")

    dates = pd.date_range(start=start_date, periods=periods, freq=freq)
    time = np.arange(periods)

    frequency = str(freq).upper()
    if frequency.startswith(('M', 'MS')):
        base_period = 12
    elif frequency.startswith(('Q', 'QS')):
        base_period = 4
    elif frequency.startswith(('W', 'W-')):
        base_period = 52
    elif frequency.startswith(('D', 'B')):
        base_period = 7
    else:
        base_period = max(2, periods // 2)

    period = min(base_period, periods // 2)
    period = max(2, period)

    trend = 100 + 2.5 * time
    seasonal_pattern = 1 + 0.12 * np.sin(2 * np.pi * time / period)
    noise = 1 + 0.03 * np.cos(2 * np.pi * time / max(period, 2))

    if model == 'multiplicative':
        sales = trend * seasonal_pattern * noise
    else:
        sales = trend + 12 * np.sin(2 * np.pi * time / period) + 3 * np.cos(
            2 * np.pi * time / max(period, 2)
        )

    sales_series = pd.Series(sales, index=dates, name='sales')
    decomposition = seasonal_decompose(
        sales_series,
        model=model,
        period=period,
        extrapolate_trend='freq',
    )

    return {
        'trend': decomposition.trend,
        'seasonal': decomposition.seasonal,
        'residual': decomposition.resid,
    }

