import csv
import collections


def task_func(csv_file, emp_prefix='EMP$$'):
    """Count CSV records for each employee."""
    should_close = False

    if isinstance(csv_file, (str, bytes)):
        csv_file = open(csv_file, newline='', encoding='utf-8')
        should_close = True

    try:
        reader = csv.DictReader(csv_file)
        if not reader.fieldnames:
            return {}

        employee_field = next(
            (
                field for field in reader.fieldnames
                if field.strip().lower().replace('_', '').replace(' ', '')
                in {'employee', 'employeeid', 'empid', 'emp'}
            ),
            reader.fieldnames[0],
        )

        counts = collections.Counter()

        for row in reader:
            employee = (row.get(employee_field) or '').strip()
            if not employee:
                continue
            if emp_prefix and not employee.startswith(emp_prefix):
                continue
            counts[employee] += 1

        return dict(counts)
    finally:
        if should_close:
            csv_file.close()

