import numpy as np
import matplotlib.pyplot as plt


def task_func(data):
    if not isinstance(data, list):
        raise TypeError("Input data must be a list of dictionaries.")
    if not data:
        raise ValueError("Input data cannot be empty.")
    if any(not isinstance(item, dict) for item in data):
        raise TypeError("Input data must be a list of dictionaries.")

    values_by_key = defaultdict(list)

    for item in data:
        for key, value in item.items():
            if isinstance(value, (bool, complex)) or not np.isscalar(value):
                raise TypeError("All dictionary values must be numeric.")
            try:
                if not np.issubdtype(type(value), np.number):
                    raise TypeError("All dictionary values must be numeric.")
            except TypeError:
                raise TypeError("All dictionary values must be numeric.")
            values_by_key[key].append(value)

    statistics = {}
    axes = []

    for key, values in values_by_key.items():
        mean = float(np.mean(values))
        standard_deviation = float(np.std(values))

        statistics[key] = {
            "mean": mean,
            "std": standard_deviation,
        }

        _, ax = plt.subplots()
        ax.bar(
            [str(key)],
            [mean],
            yerr=[standard_deviation],
            capsize=5,
        )
        ax.set_title(f"Mean and Standard Deviation for {key}")
        ax.set_ylabel("Value")
        axes.append(ax)

    return statistics, axes

import warnings
import os
import glob
import shutil
import time

def task_func(SOURCE_DIR, DEST_DIR, EXTENSIONS):
    transferred_files = []

    try:
        os.makedirs(DEST_DIR, exist_ok=True)
    except Exception as error:
        warnings.warn(f"Could not create destination directory: {error}")
        return transferred_files

    if isinstance(EXTENSIONS, str):
        EXTENSIONS = [EXTENSIONS]

    normalized_extensions = {
        extension.lower() if str(extension).startswith(".")
        else f".{str(extension).lower()}"
        for extension in EXTENSIONS
    }

    try:
        source_files = glob.glob(os.path.join(SOURCE_DIR, "*"))
    except Exception as error:
        warnings.warn(f"Could not access source directory: {error}")
        return transferred_files

    for source_path in source_files:
        if not os.path.isfile(source_path):
            continue

        filename = os.path.basename(source_path)
        extension = os.path.splitext(filename)[1].lower()

        if extension not in normalized_extensions:
            continue

        destination_path = os.path.join(DEST_DIR, filename)

        try:
            shutil.move(source_path, destination_path)
            transferred_files.append(filename)
        except Exception as error:
            warnings.warn(
                f"Could not transfer file '{filename}': {error}"
            )

    return transferred_files

import pandas as pd
from random import seed, choices


def task_func(L, num_dataframes=5, random_seed=None):
    seed(random_seed)

    if not L:
        return pd.DataFrame(), []

    columns = choices("abcdefghijklmnopqrstuvwxyz", k=3)
    df_list = [
        pd.DataFrame(choices(L, k=3), columns=columns)
        for _ in range(num_dataframes)
    ]

    if not df_list:
        return pd.DataFrame(columns=columns), []

    common_rows = df_list[0].drop_duplicates().copy()

    for df in df_list[1:]:
        common_rows = common_rows.merge(
            df.drop_duplicates(),
            on=columns,
            how="inner",
        )

    return common_rows.drop_duplicates().reset_index(drop=True), df_list

