import json
from glob import glob


def task_func(directory, string):
    def contains_string(value):
        if isinstance(value, str):
            return string in value
        if isinstance(value, dict):
            return any(
                contains_string(key) or contains_string(item)
                for key, item in value.items()
            )
        if isinstance(value, list):
            return any(contains_string(item) for item in value)
        return False

    matching_files = []

    for file_path in sorted(glob(f"{directory}/**/*.json", recursive=True)):
        try:
            with open(file_path, "r", encoding="utf-8") as file:
                data = json.load(file)
        except (OSError, json.JSONDecodeError):
            continue

        if contains_string(data):
            matching_files.append(file_path)

    return matching_files

