import json
import os
import re


def task_func(
    file_path,
    attribute,
    INPUT_JSON={
        "type": "object",
        "properties": {
            "name": {"type": str},
            "age": {"type": int},
            "email": {"type": str}
        },
        "required": ["name", "age", "email"]
    },
    EMAIL_REGEX=r"^[a-z0-9]+[\._]?[a-z0-9]+[@]\w+[.]\w{2,3}$"
):
    if not os.path.isfile(file_path):
        raise ValueError("The specified file does not exist.")

    try:
        with open(file_path, "r", encoding="utf-8") as file:
            data = json.load(file)
    except (OSError, json.JSONDecodeError) as exc:
        raise ValueError("Unable to read or parse the JSON file.") from exc

    if INPUT_JSON.get("type") is dict and not isinstance(data, dict):
        raise ValueError("The JSON root must be an object.")

    properties = INPUT_JSON.get("properties", {})
    required = INPUT_JSON.get("required", [])

    for field in required:
        if field not in data:
            raise ValueError(f"Required attribute is missing: {field}")

    for field, schema in properties.items():
        if field in data:
            expected_type = schema.get("type")
            if expected_type is not None and type(data[field]) is not expected_type:
                raise ValueError(f"Attribute '{field}' has an invalid type.")

    if "email" in data and (
        type(data["email"]) is not str
        or re.fullmatch(EMAIL_REGEX, data["email"]) is None
    ):
        raise ValueError("The email format is invalid.")

    if attribute not in data:
        raise ValueError(f"Attribute is missing: {attribute}")

    if attribute not in properties:
        raise ValueError(f"Attribute is not defined in the schema: {attribute}")

    return data[attribute]

import pytz
from dateutil import parser

def task_func(date_str, from_tz, to_tz):
    dt = parser.parse(date_str)
    source_tz = pytz.timezone(from_tz)
    target_tz = pytz.timezone(to_tz)

    if dt.tzinfo is None:
        dt = source_tz.localize(dt)
    else:
        dt = dt.astimezone(source_tz)

    return dt.astimezone(target_tz).strftime("%Y-%m-%d %H:%M:%S")

import numpy as np
from itertools import combinations
def task_func(array1, array2):
    if len(array1) != len(array2):
        raise ValueError("Input arrays must have the same length.")

    points = list(zip(array1, array2))
    if not points:
        return 0.0

    max_distance = 0.0
    for point1, point2 in combinations(points, 2):
        distance = np.linalg.norm(np.asarray(point1) - np.asarray(point2))
        max_distance = max(max_distance, float(distance))

    return max_distance

