import pandas as pd


def task_func(l, n_groups=5):
    shuffled = list(l)
    shuffle(shuffled)

    if not shuffled:
        return pd.Series([], dtype=object)

    values = shuffled * 10
    result = []

    for value in values:
        if not isinstance(value, str) or not value:
            result.append(value)
