def task_func(url='http://example.com'):
    response = requests.get(url)
    response.raise_for_status()

    try:
        soup = BeautifulSoup(response.content, 'html.parser')
    except Exception as exc:
        raise ValueError("Page content could not be parsed") from exc

    table = soup.find('table')
    if table is None:
        raise ValueError("No table found on the page")

    rows = table.find_all('tr')
    if not rows:
        raise ValueError("No table data found")

    headers = []
    first_row_headers = rows[0].find_all('th')
    if first_row_headers:
        headers = [header.get_text(strip=True) for header in first_row_headers]
        rows = rows[1:]

    data = [
        [cell.get_text(strip=True) for cell in row.find_all('td')]
        for row in rows
    ]
    data = [row for row in data if row]

    if not data:
        raise ValueError("No table data found")

    if headers:
        width = max(len(headers), max(len(row) for row in data))
        headers += [f"Unnamed: {i}" for i in range(len(headers), width)]
        data = [row + [""] * (width - len(row)) for row in data]
        return pd.DataFrame(data, columns=headers)

    return pd.DataFrame(data)

