import inspect
import types
import json


def task_func(f):
    signature = inspect.signature(f)

    arguments = list(signature.parameters.keys())
    defaults = {
        name: parameter.default
        for name, parameter in signature.parameters.items()
        if parameter.default is not inspect.Parameter.empty
    }

    annotations = {
        name: str(annotation)
        for name, annotation in getattr(f, "__annotations__", {}).items()
    }

    specifications = {
        "name": getattr(f, "__name__", type(f).__name__),
        "arguments": arguments,
        "defaults": defaults,
        "annotations": annotations,
        "is_lambda": isinstance(f, types.LambdaType)
        and getattr(f, "__name__", None) == "<lambda>",
    }

    return json.dumps(specifications, default=str)

