    if isinstance(data, dict):
        for room in ROOMS:
            if room in data:
                value = data[room]
                if isinstance(value, dict):
                    value = value.get("status", value.get("Status", "Available"))
                statuses[room] = value
    elif isinstance(data, (list, tuple)):
        for item in data:
            if isinstance(item, dict):
                room = item.get("room", item.get("Room"))
                status = item.get("status", item.get("Status", "Available"))
                if room in statuses:
                    statuses[room] = status

    report = pd.DataFrame(
        {
            "Room": ROOMS,
            "Status": [statuses[room] for room in ROOMS],
        }
