import re
import os
import glob
import mimetypes


def task_func(directory, file_pattern, suffix):
    result = {}

    try:
        regex = re.compile(file_pattern)
        regex_valid = True
    except re.error:
        regex = None
        regex_valid = False

    paths = glob.glob(os.path.join(directory, file_pattern))

    if regex_valid:
        paths.extend(glob.glob(os.path.join(directory, "*")))

    seen = set()
    for path in paths:
        if path in seen or not os.path.isfile(path):
            continue
        seen.add(path)

        filename = os.path.basename(path)
        matches_glob = path in glob.glob(os.path.join(directory, file_pattern))
        matches_regex = regex_valid and regex.match(filename) is not None

        if (matches_glob or matches_regex) and filename.endswith(suffix):
            result[filename] = mimetypes.guess_type(path)[0]

    return result

