def task_func(repo_url: str) -> dict:
    try:
        response = requests.get(repo_url, timeout=10)

        rate_limit_exceeded = (
            response.status_code == 403
            and (
                response.headers.get("X-RateLimit-Remaining") == "0"
                or "rate limit" in response.text.lower()
            )
        )

        if rate_limit_exceeded:
