    with open(config_path, "r", encoding="utf-8") as config_file:
        return json.load(config_file)

import pandas as pd
import os

def task_func(original_file_location="test.xlsx", new_file_location="new_test.xlsx", sheet_name="Sheet1"):
    if not os.path.exists(original_file_location):
        raise FileNotFoundError(original_file_location)

    with pd.ExcelFile(original_file_location) as excel_file:
        if sheet_name not in excel_file.sheet_names:
            raise ValueError(f"Sheet '{sheet_name}' does not exist in the workbook.")

    data = pd.read_excel(original_file_location, sheet_name=sheet_name)
    data.to_excel(new_file_location, sheet_name=sheet_name, index=False)

    return pd.read_excel(new_file_location, sheet_name=sheet_name)

